var i=[{title:`Was jeder Bereich leistet`,text:`Die Brustwirbelsäule ist der mittlere Abschnitt deines Rückens und lässt dich rotieren und strecken. Der Schulterkomplex umfasst das Kugelgelenk und das Schulterblatt, das über den Brustkorb gleitet. Das Greifen über den Kopf hängt davon ab, dass mehrere Bereiche zusammenarbeiten, es testet also mehr als die Dehnbarkeit des Schultergelenks.`},{title:`Bequeme Bewegung erkunden`,text:`Eine Open-Book-Rotation dreht deinen Oberkörper sanft, während deine Hüften recht still bleiben. Kontrollierte Armkreise üben die Schulterbewegung, und Katze-Kuh bewegt die Wirbelsäule in gemächlichem Tempo durch Beugung und Streckung. Bewege dich langsam, atme normal und erzwinge die Endposition nicht.`},{title:`Beweglichkeit bei deinen Hebungen`,text:`Überkopfdrücken fühlt sich möglicherweise flüssiger an, wenn sich Rippen, Schulterblätter und Arme gemeinsam bewegen. Lass beim Rudern deine Schulterblätter sich natürlich bewegen; du musst sie nicht die ganze Zeit nach hinten festhalten. Strebe flüssige Kontrolle bei der gewählten Übung an. Es gibt keine einzelne starre Haltung, die alle kopieren müssen.`},{title:`Beweglichkeit plus Kraft`,text:`Leichtes Drücken, Wandgleiten, Rudern und kontrolliertes Tragen bauen nutzbaren Bewegungsumfang und Koordination gemeinsam auf. Dehnen allein kann die passive Dehnbarkeit verbessern, ohne dir volle Kontrolle unter Last zu geben. Wenn sich eine Übung instabil oder unangenehm anfühlt, ändere Griff, Winkel oder Bewegungsumfang.`},{title:`TrainUp nutzen`,text:`Wenn dich Arbeit über Kopf an der Schulter stört, füge die Schulter im Profil als Einschränkung hinzu, mit einer Notiz. Der Plan wählt nur Übungen, die zu deinen Einschränkungen passen. Gehe bei neuem, anhaltendem oder sich verschlimmerndem Schulterschmerz zu einer Ärztin, einem Arzt oder einer Physiotherapeutin bzw. einem Physiotherapeuten, statt dich auf allgemeine Beweglichkeitsübungen zu verlassen.`}];var t=[{label:`ACE 2026: Beweglichkeit gegenüber Dehnbarkeit`,url:`https://www.acefitness.org/continuing-education/certified/may-2026/9119/mobility-vs-flexibility-why-the-difference-matters-for-movement-and-performance/`},{label:`ACE 2026: praktische Hinweise zum Dehnen`,url:`https://www.acefitness.org/continuing-education/certified/april-2026/9104/new-expert-guidance-on-stretching-what-belongs-in-your-programs/?authorScope=80`},{label:`ACE-Übungsbibliothek`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`}];var r={sections:i,sources:t};export{r as default,i as sections,t as sources};